class StageController {
    constructor() {
        this.ws = new WebSocket('wss://protocol-pulse.com/stream');
        this.initializeEventListeners();
    }

    initializeEventListeners() {
        this.ws.onmessage = (event) => {
            const data = JSON.parse(event.data);
            switch(data.type) {
                case 'transcript':
                    this.addTranscriptItem(data);
                    break;
                case 'sentiment':
                    this.updateSentimentBars(data);
                    break;
                case 'source':
                    this.addSourceItem(data);
                    break;
            }
        };

        this.ws.onerror = () => {
            this.showErrorState();
        };
    }

    addTranscriptItem(data) {
        const item = this.createTranscriptElement(data);
        const container = document.querySelector('[data-panel="transcript"]');

        // Add with animation
        item.style.opacity = '0';
        item.style.transform = 'translateY(-10px)';
        container.prepend(item);

        requestAnimationFrame(() => {
            item.style.transition = 'all 0.3s ease';
            item.style.opacity = '1';
            item.style.transform = 'translateY(0)';
        });

        // Auto-scroll to top
        container.scrollTo({ top: 0, behavior: 'smooth' });
    }

    updateSentimentBars(data) {
        Object.entries(data.sentiment).forEach(([type, value]) => {
            const bar = document.querySelector(
                `.sentiment-bar__fill--${type}`
            );
            bar.style.width = `${value}%`;
            bar.setAttribute('data-updated', 'true');

            // Remove shimmer after animation
            setTimeout(() => {
                bar.removeAttribute('data-updated');
            }, 800);
        });
    }
}

// Initialize on load
document.addEventListener('DOMContentLoaded', () => {
    new StageController();
});
```

